import{_ as r,a0 as p,w as l,s as c,ao as s,I as o,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"用 Portainer.io 來監控和管理 Docker 容器（1） | LCTT x X-CMD","titleTemplate":false,"description":"用 Portainer.io 來監控和管理 Docker 容器（1） | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Portainer.io 來監控和管理 Docker 容器（1） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Portainer.io 來監控和管理 Docker 容器（1） | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20190501 Monitor and Manage Docker Containers with Portainer.io (GUI tool) - Part-1","title":"用 Portainer.io 來監控和管理 Docker 容器（1）","tag":"202009","desc":""},"relativePath":"202009/20190501 Monitor and Manage Docker Containers with Portainer.io (GUI tool) - Part-1.md","filePath":"[post].md"}'),d={name:"202009/20190501 Monitor and Manage Docker Containers with Portainer.io (GUI tool) - Part-1.md"};function u(h,a,g,m,k,b){const t=p("Link");return l(),c("div",null,[a[19]||(a[19]=s(`<h1 id="用-portainer-io-來監控和管理-docker-容器-1" tabindex="-1">用 Portainer.io 來監控和管理 Docker 容器（1） <a class="header-anchor" href="#用-portainer-io-來監控和管理-docker-容器-1" aria-label="Permalink to “用 Portainer.io 來監控和管理 Docker 容器（1）”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202009/20/225425zaepvexqvg7nndqv.jpg" alt=""></p><p>隨着 Docker 的使用量越來越大，監控 Docker 容器正在變得更有挑戰性。每天都有大量的 Docker 容器被創建，因此如何監控它們就變得非常重要。目前已經有一些內置的工具和技術，不過對它們進行配置有一些複雜。隨着基於微服務的架構正在變成接下來事實上的標準，學會這種技術將為你的知識庫再添一項新技能。</p><p>基於上述場景，對一種輕量、健壯的鏡像管理工具的需求日益增加。Portainer.io 解決了這個問題。 Portainer.io（最新版本是 1.20.2）非常輕量，只需 2-3 個命令就可以配置好，已經在 Docker 用户中流行起來。</p><p>比起其他工具，這個工具有很多優勢，其中一些如下所示：</p><ul><li>輕量（安裝此工具僅需 2 到 3 個命令，與此同時安裝鏡像的大小在 26 M 到 30 M 之間）</li><li>健壯且易用</li><li>可用於 Docker 監控和構建</li><li>提供對 Docker 環境的詳細概況</li><li>可以管理容器、鏡像、網絡和卷</li><li>Portainer 部署方便，僅需一個 Docker 命令（可以在任意地方運行）</li><li>可以對完整的 Docker 容器環境進行監控</li></ul><p>Portainer 同時具有以下服務：</p><ul><li>社區支持</li><li>企業支持</li><li>與合作伙伴 OEM 服務一起的專業服務</li></ul><p>Portainer 的功能和特性如下：</p><pre><code>1. 配備了漂亮的儀表盤，易於使用和監控
2. 自帶大量內置模板，便於操作和創建
3. 服務支持（僅 OEM 和企業用户）
4. 對容器、鏡像、網絡、卷以及配置進行幾乎實時的監控
5. 包含 Docker 集羣監控功能
6. 功能多樣的用户管理
</code></pre>`,10)),o("p",null,[a[1]||(a[1]=n("另請閲讀：",-1)),e(t,{href:"https://www.linuxtechi.com/how-to-setup-docker-on-ubuntu-server-16-04/"},{default:i(()=>[...a[0]||(a[0]=[n("如何在 Ubuntu 16.04 / 18.04 LTS 版本中安裝 Docker CE",-1)])]),_:1})]),a[20]||(a[20]=s(`<h3 id="如何在-ubuntu-linux-rhel-centos-系統上安裝和配置-portainer-io" tabindex="-1">如何在 Ubuntu Linux / RHEL / CentOS 系統上安裝和配置 Portainer.io <a class="header-anchor" href="#如何在-ubuntu-linux-rhel-centos-系統上安裝和配置-portainer-io" aria-label="Permalink to “如何在 Ubuntu Linux / RHEL / CentOS 系統上安裝和配置 Portainer.io”">​</a></h3><p>注意：下面的安裝過程是在 Ubuntu 18.04 上完成的，但是對 RHEL 和 CentOS 同樣適用，同時假設你已經在系統上安裝了 Docker CE。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ lsb_release -a</span></span>
<span class="line"><span>No LSB modules are available.</span></span>
<span class="line"><span>Distributor ID: Ubuntu</span></span>
<span class="line"><span>Description:    Ubuntu 18.04 LTS</span></span>
<span class="line"><span>Release:        18.04</span></span>
<span class="line"><span>Codename:       bionic</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>為 Portainer 創建卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo docker volume create portainer_data</span></span>
<span class="line"><span>portainer_data</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>使用下面的 Docker 命令來運行 Portainer 容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo docker run -d -p 9000:9000 -v /var/run/docker.sock:/var/run/docker.sock -v portainer_data:/data portainer/portainer</span></span>
<span class="line"><span>Unable to find image &#39;portainer/portainer:latest&#39; locally</span></span>
<span class="line"><span>latest: Pulling from portainer/portainer</span></span>
<span class="line"><span>d1e017099d17: Pull complete</span></span>
<span class="line"><span>0b1e707a06d2: Pull complete</span></span>
<span class="line"><span>Digest: sha256:d6cc2c20c0af38d8d557ab994c419c799a10fe825e4aa57fea2e2e507a13747d</span></span>
<span class="line"><span>Status: Downloaded newer image for portainer/portainer:latest</span></span>
<span class="line"><span>35286de9f2e21d197309575bb52b5599fec24d4f373cc27210d98abc60244107</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>安裝完成之後，通過主機或 Docker 的 IP 加上 Docker 引擎使用的 9000 端口在瀏覽器中打開 Portainer。</p><p>注意：如果 Docker 所在主機的系統防火牆開啓，需要確保 9000 端口被放行，否則瀏覽器頁面將無法打開。</p><p>在我這邊，我的 Docker 主機/引擎的 IP 是 <code>192.168.1.16</code>，所以 URL 就是 <code>http://192.168.1.16:9000</code></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-Login-User-Name-Password-1024x681.jpg" alt="Portainer-Login-User-Name-Password"></p><p>在創建管理員用户時，請確保密碼是 8 個字符，同時用户名為 <code>admin</code>，然後點擊 “Create User”。</p><p>接下來進入如下所示的頁面，選中 “Local” 矩形框。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Connect-Portainer-Local-Docker-1024x538.jpg" alt="Connect-Portainer-Local-Docker"></p><p>點擊 “Connect”，</p><p>可以看到 admin 用户的漂亮首頁如下所示，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-io-Docker-Monitor-Dashboard-1024x544.jpg" alt="Portainer-io-Docker-Monitor-Dashboard"></p><p>現在 Portainer 已經準備好運行和管理你的 Docker 容器了，同時也可用於容器監控。</p><h3 id="在-portainer-中管理容器鏡像" tabindex="-1">在 Portainer 中管理容器鏡像 <a class="header-anchor" href="#在-portainer-中管理容器鏡像" aria-label="Permalink to “在 Portainer 中管理容器鏡像”">​</a></h3><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-Endpoints-1024x252.jpg" alt="Portainer-Endpoints"></p><p>檢查當前的狀態，可以看到有兩個容器已經在運行了，如果你創建另一個也會立即顯示出來。</p><p>像下面這樣，在命令列中啓動一個或兩個容器，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo docker run --name test -it debian</span></span>
<span class="line"><span>Unable to find image &#39;debian:latest&#39; locally</span></span>
<span class="line"><span>latest: Pulling from library/debian</span></span>
<span class="line"><span>e79bb959ec00: Pull complete</span></span>
<span class="line"><span>Digest: sha256:724b0fbbda7fda6372ffed586670573c59e07a48c86d606bab05db118abe0ef5</span></span>
<span class="line"><span>Status: Downloaded newer image for debian:latest</span></span>
<span class="line"><span>root@linuxtechi:/#</span></span></code></pre></div><p>然後在 Portainer 頁面中點擊刷新按鈕（會出現一條讓你確認的消息，點擊上面的 “Continue”），就可以像下面高亮顯示的一樣看到 3 個容器了。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-io-new-container-image-1024x544.jpg" alt="Portainer-io-new-container-image"></p><p>點擊上圖中紅圈圈出來的 “containers”，下一個頁面會顯示 “Dashboard Endpoint summary”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-io-Docker-Container-Dash-1024x544.jpg" alt="Portainer-io-Docker-Container-Dash"></p><p>在這個頁面中，點擊上圖高亮和紅圈圈出來的 “Containers”，就可以對容器進行監控了。</p><h3 id="以簡單的方式對容器進行監控" tabindex="-1">以簡單的方式對容器進行監控 <a class="header-anchor" href="#以簡單的方式對容器進行監控" aria-label="Permalink to “以簡單的方式對容器進行監控”">​</a></h3><p>繼續上面的步驟，就會出現一個如下所示精緻、漂亮的 “Container list” 頁面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-Container-List-1024x538.jpg" alt="Portainer-Container-List"></p><p>所有的容器都可以在這裏進行控制（停止、啓動等等）。</p><p>1、在這個頁面上，停止我們之前啓動的 “test” 容器（這是一個我們早先啓動的 debian 容器）。</p><p>選中此容器前面的複選框，然後點擊上面的“Stop”按鈕來停止。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Stop-Container-Portainer-io-dashboard-1024x447.jpg" alt="Stop-Container-Portainer-io-dashboard"></p><p>在命令列中，你也會看到這個容器現在已經停止或退出了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo docker container ls -a</span></span>
<span class="line"><span>CONTAINER ID        IMAGE                 COMMAND             CREATED             STATUS                       PORTS                    NAMES</span></span>
<span class="line"><span>d45902e717c0        debian                &quot;bash&quot;              21 minutes ago      Exited (0) 49 seconds ago                             test</span></span>
<span class="line"><span>08b96eddbae9        centos:7              &quot;/bin/bash&quot;         About an hour ago   Exited (137) 9 minutes ago                            mycontainer2</span></span>
<span class="line"><span>35286de9f2e2        portainer/portainer   &quot;/portainer&quot;        2 hours ago         Up About an hour             0.0.0.0:9000-&gt;9000/tcp   compassionate_benz</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>2、現在，在 Portainer 頁面中啓動已經停止的兩個容器（test 和 mycontainer2）</p><p>選中已停止的這兩個容器前面的複選框，然後點擊 “Start”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Start-Containers-Portainer-GUI-1024x449.jpg" alt="Start-Containers-Portainer-GUI"></p><p>你會立即看到兩條窗口提醒，內容是“容器成功啓動”，並且兩個容器的狀態變為正在運行。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Conatiner-Started-successfully-Portainer-GUI-1024x538.jpg" alt="Conatiner-Started-successfully-Portainer-GUI"></p><h3 id="一步步探索其他多種選項和特性" tabindex="-1">一步步探索其他多種選項和特性 <a class="header-anchor" href="#一步步探索其他多種選項和特性" aria-label="Permalink to “一步步探索其他多種選項和特性”">​</a></h3><p>1、點擊高亮的“Images”，你會看到如下頁面：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Docker-Container-Images-Portainer-GUI-1024x544.jpg" alt="Docker-Container-Images-Portainer-GUI"></p><p>這是可用的容器列表，其中一些可能沒在運行。這些容器可以被導入、導出或者上傳到不同的位置，截圖如下所示。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Upload-Docker-Container-Image-Portainer-GUI-1024x544.jpg" alt="Upload-Docker-Container-Image-Portainer-GUI"></p><p>2、點擊高亮的“Volumes”，顯示如下頁面：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Volume-list-Portainer-io-gui-1024x544.jpg" alt="Volume-list-Portainer-io-gui"></p><p>3、通過下面的操作，可以很容易的添加捲。點擊添加捲按鈕，出現如下頁面，在名稱輸入框中輸入卷名稱，例如 “myvol”，然後點擊 “Create the volume” 按鈕：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Volume-Creation-Portainer-io-gui-1024x544.jpg" alt="Volume-Creation-Portainer-io-gui"></p><p>新創建的卷如下所示（狀態為未使用）：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Volume-unused-Portainer-io-gui-1024x544.jpg" alt="Volume-unused-Portainer-io-gui"></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>通過上面的安裝步驟，你可以到配置和使用 Portainer.io 的多種選項是多麼簡單和精美，它提供了用於構建和監控 Docker 容器的多種功能和選項。如前所述，這個一個非常輕量的工具，因此不會給主機系統增加任何負擔。下一組選項將在本系列的第 2 部分中進行探討。</p>`,55)),o("p",null,[a[3]||(a[3]=n("另請閲讀: ",-1)),e(t,{href:"https://www.linuxtechi.com/monitor-manage-docker-containers-portainer-io-part-2/"},{default:i(()=>[...a[2]||(a[2]=[n("用 Portainer.io 來監控和管理 Docker 容器（2）",-1)])]),_:1})]),a[21]||(a[21]=o("hr",null,null,-1)),o("p",null,[a[5]||(a[5]=n("via: ",-1)),e(t,{href:"https://www.linuxtechi.com/monitor-manage-docker-containers-portainer-part1/"},{default:i(()=>[...a[4]||(a[4]=[n("https://www.linuxtechi.com/monitor-manage-docker-containers-portainer-part1/",-1)])]),_:1})]),o("p",null,[a[10]||(a[10]=n("作者：",-1)),e(t,{href:"https://www.linuxtechi.com/author/shashidhar/"},{default:i(()=>[...a[6]||(a[6]=[n("Shashidhar Soppin",-1)])]),_:1}),a[11]||(a[11]=n(" 選題：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[7]||(a[7]=[n("lujun9972",-1)])]),_:1}),a[12]||(a[12]=n(" 譯者：",-1)),e(t,{href:"https://github.com/jlztan"},{default:i(()=>[...a[8]||(a[8]=[n("jlztan",-1)])]),_:1}),a[13]||(a[13]=n(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:i(()=>[...a[9]||(a[9]=[n("wxy",-1)])]),_:1})]),o("p",null,[a[16]||(a[16]=n("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[14]||(a[14]=[n("LCTT",-1)])]),_:1}),a[17]||(a[17]=n(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:i(()=>[...a[15]||(a[15]=[n("Linux中國",-1)])]),_:1}),a[18]||(a[18]=n(" 榮譽推出",-1))])])}const f=r(d,[["render",u]]);export{x as __pageData,f as default};
